vec3 f = normalize(center - eye);
vec3 s = normalize(cross(f, up));
vec3 u = cross(s, f);

mat4 m = mat4();
m[0][0] = s.x;
m[0][1] = s.y;
m[0][2] = s.z;
m[0][3] = -dot(s, eye);
m[1][0] = u.x;
m[1][1] = u.y;
m[1][2] = u.z;
m[1][3] = -dot(u, eye);
m[2][0] = -f.x;
m[2][1] = -f.y;
m[2][2] = -f.z;
m[2][3] = dot(f, eye);
m[3][0] = 0;
m[3][1] = 0;
m[3][2] = 0;
m[3][3] = 1;

return m;

